[4731] = { en = "Beached Sea Turtle", tier = 1,
  t = "Aangespoelde zeeschildpad",
  d = "Weer liggen er resten van een zeeschildpad op de kust. Bij deze resten zit een verlaten wagen half vastgegespt aan het schild van de schildpad. Misschien hebben onbekende wezens dit dier naar de kust gedreven. Dan is het niet zelf aangespoeld, zoals sommige andere resten deden denken. Sterke Greymist murlocs wonen nu in het karkas van dit dier.$B$BIn de wagen vind je een doos met vreemde tekens erop. Misschien begrijpt Gwennyth Bly'Leggonde in Auberdine wat ze betekenen.",
  o = "Breng de Strangely Marked Box naar Gwennyth Bly'Leggonde in Auberdine.",
  p = "Hallo weer, $N. Je werk voor de Temple of the Moon is uitstekend geweest. Worden we gezegend met nog meer hulp van jou?",
  c = "Ik heb gehoord van zulke wagens als op de rug van die schildpad. Ik denk echt dat het wagens van de naga zijn. Ze gebruiken ze in de strijd, en ook om hun voorraden aan land te brengen. De tekens op de doos die je vond, zijn van de naga. Misschien werd het dier gedood toen het verder naar het zuiden ging... naar Ashenvale misschien?$B$BIk stuur deze doos zeker naar Darnassus, samen met de rest van je vondsten. Dit is voor jou. Nogmaals bedankt voor je hulp.",
  g = { {"resten", "remains (rest)"}, {"verlaten", "abandoned"}, {"vastgegespt", "buckled, strapped (vastgespen)"}, {"schild", "shell"}, {"gedreven", "driven (drijven)"}, {"aangespoeld", "washed ashore, beached (aanspoelen)"}, {"karkas", "carcass"}, {"tekens", "markings, signs (teken)"}, {"gezegend", "blessed (zegenen)"}, {"voorraden", "supplies (voorraad)"}, {"strijd", "battle"}, {"vondsten", "finds, discoveries (vondst)"} },
},

[4732] = { en = "Beached Sea Turtle", tier = 1,
  t = "Aangespoelde zeeschildpad",
  d = "Je vindt het lijk van een zeeschildpad. Het dier is een tijd geleden aangespoeld op de kust van Darkshore. Greymist murlocs hebben het bijna helemaal kaal gegeten. Het zijn dezelfde murlocs die nu hun kamp rond de resten van het dier hebben. Toch lijken er nog bruikbare monsters over te zijn. Misschien kan Gwennyth Bly'Leggonde in Auberdine ze gebruiken.",
  o = "Breng de Sea Turtle Remains naar Gwennyth Bly'Leggonde in Auberdine.",
  p = "Weer gegroet, $N. Heb je nog meer vondsten voor de Temple of the Moon?",
  c = "Heb je nog meer aangespoelde dieren gevonden, $N? Vroeger zag je vaak zeeschildpadden die vrolijk speelden bij de voet van Nordrassil, voordat Nordrassil werd vernietigd. Maar sinds de geboorte van Teldrassil zien we steeds minder van deze dieren. Sommige sterven hier, zoals we ontdekt hebben. Waarom weten we niet.$B$BMisschien helpt jouw hulp ons om dit mysterie op te lossen. Neem dit aan, in ruil voor de resten die je ons voor ons onderzoek hebt gegeven.",
  g = { {"lijk", "corpse"}, {"aangespoeld", "washed ashore, beached (aanspoelen)"}, {"kaal", "bare, picked clean"}, {"kamp", "camp"}, {"bruikbare", "usable, suitable (bruikbaar)"}, {"monsters", "samples (monster)"}, {"gegroet", "greetings (groeten)"}, {"vernietigd", "destroyed (vernietigen)"}, {"geboorte", "birth"}, {"in ruil voor", "in exchange for"}, {"onderzoek", "study, research"} },
},

[4733] = { en = "Beached Sea Creature", tier = 1,
  t = "Gestrand zeedier",
  d = "De resten van wat een reusachtige thresher lijkt, zijn aangespoeld in de rotsachtige baai van de Twilight Shore. Deze thresher is vele malen groter dan alle andere threshers die hier gezien zijn. Waar hij ook vandaan kwam, dit dier lijkt niet uit Darkshore te komen.$B$BHier en daar is het dier uit elkaar getrokken. Maar er is nog genoeg over voor een goed monster voor Gwennyth Bly'Leggonde in Auberdine.",
  o = "Breng de Sea Creature Bones naar Gwennyth Bly'Leggonde in Auberdine.",
  p = "Elune zij gedankt. Ik ben blij je weer te zien, beste $N. Het werk van de Temple of the Moon aan het vreemde aanspoelen gaat hier in Darkshore door. Heb je misschien nog iets voor ons?",
  c = "De afmetingen van de thresher die je noemt, zijn ongelooflijk. Zelfs de oudste threshers hier worden maar een klein deel zo groot. Er waren ooit grotere threshers dicht bij Teldrassil, maar er zijn er steeds minder. Ik vraag me af of het aanspoelen van deze dieren hier daarmee te maken heeft.$B$BWij onderzoeken de botten die je ons hebt gebracht. Neem intussen dit aan namens de Temple of the Moon. Dank je, $N.",
  g = { {"reusachtige", "giant (reusachtig)"}, {"rotsachtige", "rocky (rotsachtig)"}, {"baai", "bay, inlet"}, {"vele malen", "many times"}, {"uit elkaar getrokken", "pulled apart (uit elkaar trekken)"}, {"zij gedankt", "be thanked (thanks be to)"}, {"aanspoelen", "washing ashore, beaching"}, {"afmetingen", "dimensions (afmeting)"}, {"ongelooflijk", "unbelievable, mind-boggling"}, {"onderzoeken", "examine, analyse"}, {"intussen", "meanwhile"}, {"namens", "on behalf of"} },
},

[729] = { en = "The Absent Minded Prospector", tier = 1,
  t = "De verstrooide prospector",
  d = "Wat een eer was het toen Master Greywhisker mij aan het werk zette onder leiding van de grote Prospector Remtravel. Op de academie in Ironforge kende iedereen de grote ontdekkingen van Remtravel.$b$bMaar de prospector ziet nogal... eh... weinig ...van wat er om hem heen gebeurt.$b$bWe hadden bewijs gevonden van een grote samenleving. Vreselijke golems sprongen uit de grond en overspoelden de plek. Remtravel leek het niet eens te merken. Ik rende terug naar Auberdine voor hulp.$b$bReis alsjeblieft naar het zuiden en kijk of het goed gaat met de prospector!",
  o = "Reis naar het zuiden en kijk hoe het met Prospector Remtravel gaat.",
  c = "Hollee, ben jij dat? Ik heb hulp nodig bij het uitbeitelen van deze steen. Geef me mijn steenborstel, ik geloof dat ik iets zie.$b$bHé, jij bent Hollee niet! Je hebt zeker mijn steenborstel niet gezien?$b$bLaat maar, nu even niet! Ik heb de League beloofd dat ik het mysterieuze fossiel zou sturen dat ik heb gevonden. Waar is Hollee heen?$b$bZoveel werk te doen! Waar is dat mysterieuze fossiel nu... en mijn borstel... en Hollee...$b$bEn wie ben jij... het maakt niet uit, als je hier maar bent om te helpen.$b$bZeg het maar als je klaar bent om te gaan zoeken.",
  g = { {"verstrooide", "absent-minded (verstrooid)"}, {"eer", "honour"}, {"onder leiding van", "under the guidance of"}, {"ontdekkingen", "discoveries (ontdekking)"}, {"bewijs", "evidence"}, {"samenleving", "society"}, {"overspoelden", "overran, flooded (overspoelen)"}, {"merken", "notice"}, {"uitbeitelen", "chiselling (out)"}, {"steenborstel", "stone brush"}, {"mysterieuze", "mysterious (mysterieus)"}, {"fossiel", "fossil"} },
},

[731] = { en = "The Absent Minded Prospector", tier = 1,
  t = "De verstrooide prospector",
  d = "Dus, Hollee... o ja, jij bent Hollee niet. Waar is Hollee?$b$bBah, dat doet er niet toe. We moeten die steenborstel vinden... ik bedoel het mysterieuze fossiel! We moeten dat fossiel vinden. De Explorers' League in Darnassus wil vast een teken zien van wat ik heb gedaan.$b$bZeg het maar als je klaar bent, dan gaan we die borstel zoeken.... ik bedoel fossiel! We zullen iets op papier vinden waar de League tevreden mee is.$b$bBen je nu klaar?",
  o = "Bescherm Prospector Remtravel terwijl hij naar het mysterieuze fossiel zoekt. Ga daarna terug naar Archaeologist Hollee in Auberdine.",
  p = "Leeft de prospector nog?",
  c = "De sterren zij gedankt, Prospector Remtravel is veilig! Ik zei toch dat hij verstrooid was. Ik kan niet geloven dat hij daar per se wilde blijven, met al die vreselijke wezens die daar rondsluipen.",
  e = "Begeleid Prospector Remtravel",
  g = { {"dat doet er niet toe", "that's beside the point"}, {"steenborstel", "stone brush"}, {"mysterieuze", "mysterious (mysterieus)"}, {"teken", "sign, indication"}, {"op papier", "in writing"}, {"tevreden", "satisfied"}, {"bescherm", "protect (beschermen)"}, {"verstrooid", "absent-minded"}, {"per se", "insisted on, absolutely"}, {"rondsluipen", "lurk about, sneak around"}, {"begeleid", "escort (begeleiden)"} },
},

[741] = { en = "The Absent Minded Prospector", tier = 1,
  t = "De verstrooide prospector",
  d = "Dus de prospector wil het mysterieuze fossiel naar de Explorers' League in Darnassus sturen? Het voelt niet goed om zonder hem uit Darkshore weg te gaan.$b$bHier, $n. Breng het mysterieuze fossiel naar Chief Archaeologist Greywhisker in Darnassus.",
  o = "Breng het mysterieuze fossiel naar Chief Archaeologist Greywhisker in Darnassus.",
  p = "Wat kan ik voor je doen, $R?",
  c = "O jee! Alleen Prospector Remtravel kan zo'n vondst doen!",
  g = { {"prospector", "prospector"}, {"mysterieuze", "mysterious (mysterieus)"}, {"fossiel", "fossil"}, {"het voelt niet goed", "it doesn't feel right"}, {"o jee", "oh my"}, {"vondst", "find, discovery"} },
},

[942] = { en = "The Absent Minded Prospector", tier = 1,
  t = "De verstrooide prospector",
  d = "Dit fossiel lijkt heel erg op een fossiel dat ik ooit in Ironforge heb gezien. Een archeoloog met de naam Flagongut nam het mee naar ons jaarlijkse congres van de Explorers' League. Hij geloofde dat het fossiel een kracht had die je op een of andere manier kon vrijmaken.$b$bHet laatste wat ik hoorde, is dat Flagongut zich had teruggetrokken in de Deepwater Tavern in Menethil Harbor. Hij wachtte op begeleiding naar de Whelgar Excavation Site. Zoek hem op en laat hem Remtravels fossiel zien. Misschien kan hij de geheimen van het verleden onthullen.$b$bHet schip naar Menethil vertrekt uit Auberdine.",
  o = "Breng het mysterieuze fossiel naar Archaeologist Flagongut in Menethil Harbor.",
  p = "Wat heb je daar, vriend?",
  c = "O jee! Zeg je dat dit uit de verre landen van Kalimdor komt?$B$BGeweldig! Gewoon geweldig!",
  g = { {"lijkt heel erg op", "bears a striking resemblance to (lijken op)"}, {"archeoloog", "archaeologist"}, {"jaarlijkse", "annual (jaarlijks)"}, {"congres", "conference"}, {"op een of andere manier", "somehow"}, {"vrijmaken", "unlock, release"}, {"teruggetrokken", "holed up, withdrawn (zich terugtrekken)"}, {"begeleiding", "escort"}, {"onthullen", "reveal"}, {"verleden", "past"}, {"vertrekt", "departs (vertrekken)"}, {"verre", "distant (ver)"} },
},

[951] = { en = "Mathystra Relics", tier = 1,
  t = "Relieken van Mathystra",
  d = "Het perkament dat je bij de Master's Glaive vond, is een bladzijde uit een oude tekst... geschreven door elfen! Er ligt een zware vloek op, en het is besmet door de verdorvenheid van de Twilight's Hammer. Maar het lijkt erop dat de sekte oude elfenmagie gebruikt om hun oude meesters terug te brengen naar onze wereld.$B$BReis naar de ruïnes van Mathystra in het noordoosten. Zoek daar naar oude relieken tussen het gras en de gebroken stenen. Als we ze bestuderen, kunnen we misschien ontdekken hoe de Twilight's Hammer de magie van de elfen wil misbruiken.",
  o = "Breng 6 Mathystra Relics naar Onu bij de Grove of the Ancients.",
  p = "$N. Heeft je gegraaf in de Ruins of Mathystra iets opgeleverd?",
  c = "Dank je. Deze relieken komen uit een tijd waarin Mathystra schitterde. Dat ooit zo grote bolwerk van de elfen is verbleekt, maar er zijn nog stukjes van zijn magie over. Laten we hopen dat we de geheimen van die plek eerder ontdekken dan onze vijanden...$b$bWees waakzaam, $N.",
  g = { {"relieken", "relics (reliek)"}, {"perkament", "parchment"}, {"vloek", "curse"}, {"besmet", "tainted, infected (besmetten)"}, {"verdorvenheid", "corruption"}, {"sekte", "cult"}, {"bestuderen", "study"}, {"misbruiken", "exploit, misuse"}, {"gegraaf", "digging, rooting around"}, {"opgeleverd", "yielded, produced (opleveren)"}, {"schitterde", "shone (schitteren)"}, {"bolwerk", "bastion, stronghold"}, {"verbleekt", "faded (verbleken)"}, {"waakzaam", "vigilant"} },
},

[968] = { en = "The Powers Below", tier = 1,
  t = "De machten van beneden",
  d = "Het boek is erg versleten en vol krassen, maar de titel op de kaft kun je nog lezen:$B$BThe Powers Below$B$BIn het boek staat een lijst met namen die je niet kunt uitspreken, met onheilspellende titels, manieren van aanbidding en offers die ze het liefst krijgen... Bij veel van die offers gaat het om levende, mensachtige wezens.$B$BAan de binnenkant van de kaft staan deze woorden: \"Bonegrip's Runes and Dooms, The Forlorn Cavern, Ironforge. Eigenaar: Gerrig Bonegrip.\"$B$BAls Bonegrip zulke boeken verkoopt, wil hij dit boek misschien terugkopen.",
  o = "Breng het Book: The Powers Below naar Gerrig Bonegrip in de Forlorn Cavern, Ironforge.",
  p = "Hallo, $Gmeneer:mevrouw;.$B$BHeb je misschien interesse in een van mijn boekwerken?",
  c = "Ah, een exemplaar van The Powers Below. Een interessante tekst is dit. En sommigen vinden hem misschien nuttig...$B$BMaar dit exemplaar is in slechte staat. En kijk hier! Er staan aantekeningen in de kantlijn van bijna elke bladzijde!$B$BHm... ik ken dit exemplaar. Ik heb het vorig jaar aan Bolgar verkocht. Ben jij... een vriend van hem? Ja, dat dacht ik al. Je hebt hetzelfde vuur in je ogen!$B$BNou, een vriend van Bolgar is per definitie een vriend van mij. En wij zorgen voor de onzen, toch?",
  g = { {"machten", "powers (macht)"}, {"versleten", "worn (verslijten)"}, {"krassen", "scratches (kras)"}, {"kaft", "cover (of a book)"}, {"uitspreken", "pronounce"}, {"onheilspellende", "foreboding, ominous (onheilspellend)"}, {"aanbidding", "worship"}, {"offers", "sacrifices (offer)"}, {"mensachtige", "humanoid (mensachtig)"}, {"boekwerken", "tomes (boekwerk)"}, {"exemplaar", "copy"}, {"aantekeningen", "notes (aantekening)"}, {"kantlijn", "margin"}, {"per definitie", "by definition"}, {"de onzen", "our own (people)"} },
},

[986] = { en = "A Lost Master", tier = 1,
  t = "Een verloren meester",
  d = "$N, je vaardigheden hebben me al geholpen bij mijn taak. Mag ik je nog een keer lastigvallen om Grimclaw en zijn meester Volcor te helpen? Ook kan ik een magische mantel voor je maken. Daarmee kun je ongestoord langs de wezens van Darkshore lopen terwijl je hem zoekt.$B$BOm de mantel te maken heb ik vijf mooie moonstalker-vachten nodig van een Moonstalker Sire of een Moonstalker Matriarch. Dan heb ik genoeg materiaal. Je vindt de katten bij de Wildbend River in het zuiden, of nog verder naar het zuiden bij Ashenvale.",
  o = "Vind 5 Fine Moonstalker Pelts en breng ze naar Terenthis in Auberdine.",
  p = "Met een goed geweten kan ik je niet naar Volcor laten zoeken voordat ik die mantel voor je heb gemaakt.",
  c = "Deze zijn prima, $N. Ik begin meteen aan de mantel.$B$BGeef me even de tijd en kom dan terug.$B$BO, nog één ding: als je de betovering van de mantel hebt gebruikt, kun je minder met anderen doen. Doe niet meer dan met anderen praten, als het lukt. Veel meer dan dat kan de illusie verbreken.",
  g = { {"vaardigheden", "skills (vaardigheid)"}, {"taak", "task, endeavour"}, {"lastigvallen", "bother, impose on"}, {"mantel", "cloak"}, {"ongestoord", "undisturbed, unhindered"}, {"vachten", "pelts, furs (vacht)"}, {"geweten", "conscience"}, {"meteen", "immediately"}, {"betovering", "enchantment"}, {"als het lukt", "if you can help it"}, {"illusie", "illusion"}, {"verbreken", "break, dispel"} },
},

[993] = { en = "A Lost Master", tier = 1,
  t = "Een verloren meester",
  d = "De mantel is klaar, $N. Het is tijd om Volcor te vinden. Ik kan alleen hopen dat we op tijd zijn.$B$BAls je de magie van de mantel gebruikt, duurt die niet lang; misschien vijf minuten. Jij moet zelf weten wanneer je hem gebruikt. Ik zou wachten tot je Grimclaw vindt.$B$BAls het klopt wat hij me heeft verteld, vind je zijn meester in een grot ten zuiden van hier. Grimclaw wacht langs de weg op je. Zwaai naar hem als je hem ziet, dan wijst hij je de weg naar zijn meester.",
  o = "Vind Volcor in Darkshore en geef hem de Enchanted Moonstalker Cloak.",
  c = "Geweldig! Terenthis heeft iemand gevonden om me te helpen.$b$bEn kijk, een moonstalker-mantel...<hoest> O... dat doet pijn. Dank je, $N.$b$bDe furbolgs hebben me verwond voordat ik aan ze kon ontsnappen. Geef me even, dan kan ik vast weer verder praten.",
  g = { {"mantel", "cloak"}, {"op tijd", "in time"}, {"duurt", "lasts (duren)"}, {"als het klopt", "if it is true"}, {"grot", "cave"}, {"ten zuiden van", "south of"}, {"zwaai", "wave (zwaaien)"}, {"wijst", "points, shows (wijzen)"}, {"hoest", "cough (hoesten)"}, {"verwond", "wounded (verwonden)"}, {"ontsnappen", "escape"} },
},

[995] = { en = "Escape Through Stealth", tier = 1,
  t = "Ontsnappen door te sluipen",
  d = "Goed dan... als je het zeker weet, sluipen we hier weg. Laten we gaan als je klaar bent.$B$BOnthoud: als je ontsnapt bent, zie je Terenthis weer in Auberdine. Ik ga daar zelf heen, want ik ben waarschijnlijk sneller dan jij.",
  o = "Ontsnap uit de grot van de furbolgs en ga naar Terenthis in Auberdine.",
  p = "Ja, $n?",
  c = "$N! Ik ben blij dat je veilig terug bent. Door jouw hulp aan Volcor heb ik weer vertrouwen dat we de problemen hier in Darkshore en daarbuiten kunnen overwinnen.",
  e = "Help Volcor uit de grot te ontsnappen",
  g = { {"sluipen", "sneak"}, {"als je het zeker weet", "if you're sure"}, {"onthoud", "remember (onthouden)"}, {"ontsnapt", "escaped (ontsnappen)"}, {"waarschijnlijk", "probably"}, {"vertrouwen", "faith, trust"}, {"daarbuiten", "beyond"}, {"overwinnen", "overcome"} },
},

[2078] = { en = "Gyromast's Revenge", tier = 1,
  t = "Gyromasts wraak",
  d = "Landrot, jij moet mijn eerste stuurman vinden.$B$BNeem deze sleutel, stop hem in zijn kop en breng hem hier terug, om de kapitein te dienen.$B$BDie murlocs en hun leider worden niet blij als mijn eerste stuurman ze te pakken krijgt!",
  o = "Vind Gelkak's First Mate, de Threshwackonator 4100, en leid hem terug naar Gelkak.",
  p = "Waar is mijn eerste stuurman, $N? Boeien en haaien voor jou, als je niet opschiet!",
  c = "Jarrr... Jij bent meer dan een laffe zeerob, landrot.$B$BDe kapitein maakt je misschien dekzwabber op het achterdek als je zo doorgaat...",
  o1 = "Gelkak's First Mate",
  g = { {"wraak", "revenge"}, {"landrot", "landlubber"}, {"eerste stuurman", "first mate"}, {"kop", "head (informal)"}, {"dienen", "serve"}, {"te pakken krijgt", "gets hold of (te pakken krijgen)"}, {"boeien", "shackles (boei)"}, {"haaien", "sharks (haai)"}, {"opschiet", "hurry (opschieten)"}, {"laffe", "cowardly (laf)"}, {"zeerob", "sea dog"}, {"dekzwabber", "deck swabby"}, {"achterdek", "poop deck"} },
},

[2098] = { en = "Gyromast's Retrieval", tier = 1,
  t = "Terughalen voor Gyromast",
  d = "Een piratenleven is niet makkelijk, landrot. Het gaat niet alleen om plunderen en drank! Helaas is mijn schip vlak voor de kust gezonken, door die vervelende Threshadons.$B$BWat ik nodig heb, is dat mijn eerste stuurman weer werkt!$B$BToen ik aanspoelde, brak de sleutel van mijn eerste stuurman op de rotsen. De beesten van Darkshore hebben de stukken gestolen. Uit mijn ooghoek zag ik een paar van die Ragin' Crawlers, Ferocious Foreststrider en murlocs in het wrak rommelen....",
  o = "Vind de drie stukken van Gelkak's Key en breng ze terug naar Gelkak Gyromast.",
  p = "Heb je mijn kapotte sleutel gevonden, landrot?",
  c = "Halt, jij schurftige zeerob! Het is je gelukt! Snel werkt mijn eerste stuurman weer, en die beesten weten niet wat ze overkomt!$B$BHrm, heb je mijn eerste stuurman gezien?",
  g = { {"piratenleven", "pirate's life"}, {"landrot", "landlubber"}, {"plunderen", "plundering"}, {"helaas", "alas, unfortunately"}, {"gezonken", "sunk (zinken)"}, {"vervelende", "pesky, annoying (vervelend)"}, {"aanspoelde", "washed up (aanspoelen)"}, {"gestolen", "stolen (stelen)"}, {"ooghoek", "corner of the eye"}, {"wrak", "wreckage"}, {"rommelen", "rummage"}, {"schurftige", "scurvy, mangy (schurftig)"}, {"zeerob", "sea dog"}, {"wat ze overkomt", "what hit them (overkomen)"} },
},

[5321] = { en = "The Sleeper Has Awakened", tier = 1,
  t = "De slaper is wakker geworden",
  d = "Ik was op weg naar Maestra's Post om Liladris Moonriver te ontmoeten. Maar ik besloot hier even te stoppen voor een kort dutje. Sinds ik wakker werd uit de smaragden droom, ben ik zo slaperig...$B$B<geeuw>$B$BWil je me de weg wijzen? Ik heb gehoord dat Maestra's Post ten zuiden van hier ligt, langs de weg in Ashenvale. Het kan gevaarlijk zijn, dus ik hoop dat je een paar vrienden hebt die met ons meegaan.$B$BTot slot: ik val misschien in slaap. Als je me ooit wakker moet maken, gebruik dan mijn hoorn. Je vindt hem in de kist hier.",
  o = "Begeleid Kerlonian Evershade naar Liladris Moonriver bij Maestra's Post in Ashenvale.",
  p = "Is Kerlonian al aangekomen?",
  c = "O, ik ben zo blij dat Kerlonian het gehaald heeft! En ik vind hem vast ergens hier in de buurt terwijl hij slaapt, of niet?$b$bDank je dat je hem de weg hebt gewezen, $N.",
  e = "Begeleid Kerlonian Evershade naar Maestra's Post",
  g = { {"slaper", "sleeper"}, {"besloot", "decided (besluiten)"}, {"dutje", "nap"}, {"smaragden", "emerald"}, {"slaperig", "sleepy"}, {"geeuw", "yawn (geeuwen)"}, {"de weg wijzen", "show the way"}, {"tot slot", "lastly"}, {"hoorn", "horn"}, {"kist", "chest"}, {"begeleid", "escort (begeleiden)"}, {"het gehaald heeft", "made it (het halen)"} },
},

[970] = { en = "The Tower of Althalaxx", tier = 2,
  t = "De Tower of Althalaxx",
  d = "De brief van Balthule is ernstig. Deze Cult of the Dark Strand is een doorn in mijn oog, en hij moet verdwijnen. Ik heb al te maken gehad met wat Dark Strand-tuig ten noordoosten van hier, bij Ordil'Aran. Een van hen heeft een zielensteen. Ik denk dat daarin het geheim van de macht van de sekte zit.$b$bBreng hem naar me, dan kan ik de geheimen die erin zitten ontcijferen.",
  o = "Verzamel een Glowing Soul Gem en breng hem naar Delgren the Purifier bij Maestra's Post.",
  p = "Heb je die zielensteen al?",
  c = "Hmm, er zit donkere magie op deze zielensteen. Laten we eens kijken wat erin gevangen zit, goed?",
