[994] = { en = "Escape Through Force", tier = 2,
  t = "Ontsnappen met geweld",
  d = "Goed, $N, dan wordt het geweld. Laten we hier weggaan zodra je klaar bent. We vechten ons een weg naar beneden, naar de weg. Grimclaw is daar als het goed is nog. Daar gaan we ieder onze eigen kant op.$B$BTerenthis wil jouw versie van het verhaal meteen horen. Ga dus naar Auberdine als we hier uit zijn.",
