},

[943] = { en = "The Absent Minded Prospector", tier = 2,
  t = "De verstrooide prospector",
  d = "Prospector Whelgar heeft het oorspronkelijke fossiel nu bij zijn opgraving in de Wetlands. Toen ik de Stone of Relu ontdekte, dacht ik dat die de sleutel was om het mysterie van het fossiel op te lossen.$b$bOnderweg naar Whelgar werd ik aangevallen door raptors, en ik verloor het relikwie. Ik weet niet welk van die gevlekte beesten het relikwie heeft ingeslikt. Maar als jij het terug kunt halen, kan ik de kracht van deze voorwerpen vrijmaken.$B$BBreng me zowel de Stone of Relu als het oorspronkelijke fossiel dat hij heeft.",
  o = "Archaeologist Flagongut in Menethil Harbor wil dat je hem de Stone of Relu en Flagongut's Fossil brengt.",
