  d = "Ilkrud Magthrull. Ja, ik weet wie dat is. Hij is een ork, een machtige heksenmeester. Hij woont bij de Fire Scar Shrine, een plek van groot kwaad in het zuidwesten van Ashenvale.$b$bTot nu toe was hij niet veel meer dan een ergernis, en ik had nog niets tegen hem gedaan. Maar het lijkt erop dat zijn tijd gekomen is.",
  o = "Breng Ilkrud Magthrull's Tome naar Delgren the Purifier bij Maestra's Post.",
  p = "Je ziet er een beetje geschrokken uit, $n. Gaat het wel?",
