},

[1140] = { en = "The Tower of Althalaxx", tier = 2,
  t = "De Tower of Althalaxx",
  d = "Het schrift van de orks is nauwelijks beter dan het gekrabbel van een kind. Veel leden van mijn orde lachten me uit toen ik besloot hun taal te leren. Maar ik vind het nuttig om mijn vijanden beter te begrijpen.$b$bUit Ilkruds gekrabbel blijkt dat Athrikus nog twee zielenstenen heeft. Ze worden bewaard in Night Run en Satyrnaar, gebieden in het noordoosten van Ashenvale die in handen van saters zijn.$b$bWees voorzichtig daar, $n. De bebloede tempels van de saters kunnen zelfs een ervaren $c zoals jij van streek maken.",
  o = "Bevrijd de gevangen Highborne-zielen in Night Run en Satyrnaar en ga dan terug naar Delgren the Purifier bij Maestra's Post.",
  p = "Ik heb ooit gefluister gehoord dat de geschiedenis van de saters op een of andere manier verbonden is met die van de nachtelfen. Maar mijn gewaardeerde gastheren praten er liever niet over.",
  c = "Misschien mochten de saters te lang in het bos blijven. Ik praat er met Elissa over als ik weer naar Auberdine ga.$B$BToch: nu de zielenstenen vernietigd zijn, is de macht van Athrikus veel kleiner. We moeten deze kans grijpen om hem en zijn sekte uit te schakelen.",
  o1 = "Bevrijd de Highborne-ziel in Night Run",
  o2 = "Bevrijd de Highborne-ziel in Satyrnaar",
  g = { {"schrift", "writing, script"}, {"nauwelijks", "hardly, little"}, {"gekrabbel", "scribbling"}, {"orde", "order (group)"}, {"lachten me uit", "scoffed at me (uitlachen)"}, {"blijkt", "appears, turns out (blijken)"}, {"bewaard", "kept, held (bewaren)"}, {"saters", "satyrs (sater)"}, {"bebloede", "blood-soaked (bebloed)"}, {"ervaren", "experienced, seasoned"}, {"van streek maken", "unsettle, upset"}, {"gefluister", "whisper(s)"}, {"gewaardeerde", "esteemed (gewaardeerd)"}, {"gastheren", "hosts (gastheer)"}, {"uit te schakelen", "eliminate (uitschakelen)"} },
},

[1167] = { en = "The Tower of Althalaxx", tier = 2,
  t = "De Tower of Althalaxx",
  d = "Voordat je het tegen Athrikus opneemt, is het waarschijnlijk verstandig om eerst met Balthule te overleggen. Ik weet zeker dat hij de Tower goed in de gaten heeft gehouden. Misschien heeft hij informatie over wat er onlangs is gebeurd.",
  o = "Praat met Balthule Shadowstrike bij de Tower of Althalaxx.",
  c = "Ah, fijn je weer te zien, $N! De vreemdste dingen gebeuren hier. Ik ben blij dat je er bent!$B$BHet was heel vreemd, $N. Alles leek normaal... nou ja, zo normaal als het hier ooit is... en toen was er opeens een verblindende lichtflits in de bovenste kamer van de toren. Daarna kwam het geschreeuw. De kreten scheurden door de lucht, en af en toe sloeg de bliksem in de grond. Wat is er aan de hand?",
  g = { {"het tegen ... opneemt", "confront (het opnemen tegen)"}, {"verstandig", "wise"}, {"overleggen", "consult"}, {"in de gaten heeft gehouden", "has kept watch on (in de gaten houden)"}, {"onlangs", "recently"}, {"verblindende", "blinding (verblindend)"}, {"lichtflits", "flash of light"}, {"geschreeuw", "screaming"}, {"kreten", "cries (kreet)"}, {"scheurden", "split, tore (scheuren)"}, {"af en toe", "from time to time"}, {"bliksem", "lightning"}, {"aan de hand", "going on"} },
},

})

